function searchItemCard(i, selected) {
  const sel = selected ? theme.reverse(' > ') : '   '
  const name = selected ? bold(i.full_name) : dim(i.full_name)
  const desc = i.description || 'No description'
  return [
    `${sel}${name}`,
    `   ${desc}`,
    `   ⭐ ${i.stargazers_count} · ${i.language || 'N/A'}`,
    `   rolecraft install ${i.full_name}`,
  ]
}
